39	export const useMemoViewDerived = () => {
40	  const { memo, isArchived, readonly } = useMemoViewContext();
41	  const { timeBasis } = useView();
42	  const location = useLocation();
43	
44	  const isInMemoDetailPage = location.pathname.startsWith(`/${memo.name}`) || location.pathname.startsWith("/memos/shares/");
45	  const commentAmount = computeCommentAmount(memo);
46	
47	  const createTime = memo.createTime ? timestampDate(memo.createTime) : undefined;
48	  const updateTime = memo.updateTime ? timestampDate(memo.updateTime) : undefined;
49	  const displayTime = timeBasis === "update_time" ? updateTime : createTime;
50	  const isDisplayingUpdatedTime =
51	    timeBasis === "update_time" && !!createTime && !!updateTime && updateTime.getTime() !== createTime.getTime();
52	  const relativeTimeFormat: "datetime" | "auto" =
53	    displayTime && Date.now() - displayTime.getTime() > RELATIVE_TIME_THRESHOLD_MS ? "datetime" : "auto";
54	
55	  return {
56	    isArchived,
57	    readonly,
58	    isInMemoDetailPage,
59	    commentAmount,
60	    createTime,
61	    updateTime,
62	    displayTime,
63	    isDisplayingUpdatedTime,
64	    relativeTimeFormat,
65	  };
66	};
